"""Fresh A4 calendar/hierarchy authorship; common frame only, no shipped input."""
import runpy,json
ctx=runpy.run_path('scripts/qa/stress2/author.py');save=ctx['save'];frame=ctx['frame'];CASES=ctx['CASES'];CASES.clear();OUT=ctx['OUT'];DATE=ctx['DATE'];MONTH=ctx['MONTH'];COUNTRY=ctx['COUNTRY'];CAT=ctx['CAT'];SUBCAT=ctx['SUBCAT'];PRODUCT=('Product Lookup','ProductName')
