s={'date':{'kind':'time'},'value':{'kind':'measure'}};o=frame('38 - Daily revenue - one-dimensional heat strip',s);o['grid']={'left':75,'right':40,'top':210,'height':90,'containLabel':True};o['yAxis']={'type':'category','data':['Revenue'],'axisLabel':{'color':'#cbd5e1'}};o['xAxis']['data']='$slot.date.values';o['xAxis']['axisLabel']['formatterTemplate']='{value:date}';o['legend']['show']=False;o['visualMap']={'min':'$slot.value.min','max':'$slot.value.max','left':'center','bottom':100,'orient':'horizontal','inRange':{'color':['#172554','#2dd4bf']},'textStyle':{'color':'#cbd5e1'}};o['series']=[{'type':'heatmap','data':'$slot.value.cells'}]
save(38,'daily-heat-strip',o['title']['text'],[DATE],['Total Revenue'],o,slots=s)
s={'month':{'kind':'time'},'country':{'kind':'dimension'},'value':{'kind':'measure'}};o=frame('39 - Country revenue over months - lasagna plot',s);o['xAxis']['data']='$slot.month.categories';o['xAxis']['axisLabel']['formatterTemplate']='{value:date}';o['yAxis']={'type':'category','data':'$slot.country.categories','axisLabel':{'color':'#cbd5e1'}};o['legend']['show']=False;o['visualMap']={'min':'$slot.value.min','max':'$slot.value.max','left':'center','bottom':10,'orient':'horizontal','inRange':{'color':['#172554','#2dd4bf']},'textStyle':{'color':'#cbd5e1'}};o['series']=[{'type':'heatmap','data':'$slot.value.matrix'}]
save(39,'country-lasagna',o['title']['text'],[MONTH,COUNTRY],['Total Revenue'],o,slots=s)
s={'category':{'kind':'dimension'},'subcategory':{'kind':'dimension'},'revenue':{'kind':'measure'},'profit':{'kind':'measure'}};o=noaxes(frame('40 - Category / subcategory - area revenue, colour profit',s));o['series']=[{'type':'treemap','top':80,'bottom':90,'left':25,'right':25,'data':'$calc.tree.children','visualDimension':1,'visualMin':'$slot.profit.min','visualMax':'$slot.profit.max','colorMappingBy':'value','color':['#312e81','#2dd4bf'],'leafDepth':2,'label':{'show':True,'formatterTemplate':'{name}','color':'#f8fafc'},'upperLabel':{'show':True,'height':25,'color':'#f8fafc'},'itemStyle':{'borderColor':'#1e293b','borderWidth':3,'gapWidth':2},'breadcrumb':{'show':False},'levels':[{}, {'itemStyle':{'borderColor':'#1e293b','borderWidth':3,'gapWidth':3}}]}]
o['tooltip']['formatterTemplate']='{name} | Revenue {value.0:thousands} | Profit {value.1:thousands}'
save(40,'treemap-secondary-colour',o['title']['text'],[CAT,SUBCAT],['Total Revenue','Total Profit'],o,slots=s,transforms=[{'hierarchy':{'levels':['category','subcategory'],'value':'revenue','color':'profit'},'as':'tree'}])
s={'category':{'kind':'dimension'},'subcategory':{'kind':'dimension'},'revenue':{'kind':'measure'}};o=noaxes(frame('41 - Revenue treemap - click a category, use breadcrumb to return',s));o['series']=[{'type':'treemap','name':'Products','itemStyle':{'borderColor':'#1e293b','borderWidth':3,'gapWidth':2},'top':80,'bottom':70,'left':25,'right':25,'data':'$calc.tree.children','leafDepth':1,'nodeClick':'zoomToNode','roam':False,'label':{'show':True,'color':'#f8fafc'},'upperLabel':{'show':True,'height':24,'color':'#f8fafc'},'breadcrumb':{'show':True,'bottom':15,'itemStyle':{'color':'#334155','textStyle':{'color':'#f8fafc'}}}}]
save(41,'treemap-drill',o['title']['text'],[CAT,SUBCAT],['Total Revenue'],o,slots=s,transforms=[{'hierarchy':{'levels':['category','subcategory'],'value':'revenue'},'as':'tree'}])
s={'category':{'kind':'dimension'},'subcategory':{'kind':'dimension'},'product':{'kind':'dimension'},'revenue':{'kind':'measure'}};o=noaxes(frame('42 - Category / subcategory / product revenue - sunburst',s));o['series']=[{'type':'sunburst','center':['50%','54%'],'radius':['8%','66%'],'data':'$calc.tree.children','nodeClick':'rootToNode','label':{'show':True,'rotate':'radial','fontSize':10,'width':60,'overflow':'truncate','minAngle':9,'color':'#e2e8f0'},'itemStyle':{'borderColor':'#0b0b12','borderWidth':2}}]
