s={'category':{'kind':'dimension'},'subcategory':{'kind':'dimension'},'revenue':{'kind':'measure'}};o=frame('43 - Revenue hierarchy - rectangular icicle partition',s);o['legend']['show']=False;o['grid']={'left':55,'right':30,'top':100,'bottom':90,'containLabel':True};o['xAxis']={'type':'value','min':0,'max':1,'axisLabel':{'formatterTemplate':'{value:percent}','color':'#cbd5e1'}};o['yAxis']={'type':'category','inverse':True,'data':['Category','Subcategory'],'axisLabel':{'color':'#cbd5e1'}}
o['series']={'concat':[{'repeat':'$calc.tree.nodes','template':{'type':'bar','name':'Offset','stack':'$item.id','data':'$item.base','barGap':'-100%','barWidth':'85%','itemStyle':{'opacity':0},'silent':True}}, {'repeat':'$calc.tree.nodes','template':{'type':'bar','name':'$item.name','stack':'$item.id','data':'$item.data','barGap':'-100%','barWidth':'85%','label':{'show':True,'position':'inside','formatterTemplate':'{seriesName}','fontSize':11,'width':90,'overflow':'truncate','color':'#ffffff'},'labelLayout':{'hideOverlap':True},'itemStyle':{'borderColor':'#0b0b12','borderWidth':1}}}]}
save(43,'icicle-partition',o['title']['text'],[CAT,SUBCAT],['Total Revenue'],o,slots=s,transforms=[{'hierarchy':{'levels':['category','subcategory'],'value':'revenue','layout':'partition'},'as':'tree'}])
s={'category':{'kind':'dimension'},'subcategory':{'kind':'dimension'},'revenue':{'kind':'measure'}};o=frame('44 - Revenue hierarchy - nested circle packing',s);o['legend']['show']=False;o['grid']={'left':'center','top':100,'width':400,'height':400};o['xAxis']={'type':'value','min':0,'max':400,'show':False};o['yAxis']={'type':'value','min':0,'max':400,'inverse':True,'show':False};o['series']={'repeat':'$calc.tree.nodes','template':{'type':'scatter','name':'$item.name','data':['$item.data'],'z':'$item.depth','itemStyle':{'opacity':0.6,'borderColor':'#cbd5e1','borderWidth':1},'label':{'show':True,'formatterTemplate':'{name}','color':'#ffffff','fontSize':10},'labelLayout':{'hideOverlap':True}}}
save(44,'circle-packing',o['title']['text'],[CAT,SUBCAT],['Total Revenue'],o,slots=s,transforms=[{'hierarchy':{'levels':['category','subcategory'],'value':'revenue','layout':'pack','size':400},'as':'tree'}])
for n,slug,layout,orient,title in [(45,'orthogonal-tree','orthogonal','LR','Category to subcategory revenue - orthogonal tree'),(46,'radial-tree','radial','LR','Category to subcategory revenue - radial tree'),(47,'taxonomy-org-chart','orthogonal','TB','Product taxonomy org chart - no employee data in model'),(48,'dendrogram-values','orthogonal','LR','Product taxonomy - dendrogram with leaf revenue')]:
 s={'category':{'kind':'dimension'},'subcategory':{'kind':'dimension'},'revenue':{'kind':'measure'}};o=noaxes(frame(f'{n} - {title}',s));o['series']=[{'type':'tree','data':[{'name':'Products','children':'$calc.tree.children'}],'top':90,'bottom':50,'left':100,'right':180,'layout':layout,'orient':orient,'edgeShape':'polyline' if n in (45,47) else 'curve','initialTreeDepth':-1,'expandAndCollapse':True,'symbolSize':10,'label':{'position':'left','color':'#cbd5e1','fontSize':11},'leaves':{'label':{'position':'right','formatterTemplate':'{name}: {value:thousands}' if n==48 else '{name}','color':'#e2e8f0','fontSize':10}},'lineStyle':{'color':'#64748b'},'itemStyle':{'color':'#2dd4bf'}}]
 if n==46:
  o['series'][0].update({'top':135,'bottom':115,'left':140,'right':180})
