  o['series'][0].update({'left':50,'right':50,'bottom':95,'symbol':'rect','symbolSize':[14,14],'label':{'position':'top','color':'#ffffff'},'leaves':{'label':{'position':'bottom','rotate':45,'fontSize':10,'color':'#cbd5e1'}}})
